//! crypto/cipher, crypto/aes, crypto/des and crypto/rc4, ported from Go's
//! aes_test.go, des_test.go, rc4_test.go, cbc_aes_test.go, cfb_test.go,
//! ctr_aes_test.go, ofb_test.go, gcm_test.go and the shared cryptotest
//! properties (block inverse, chunked streams, AEAD round trips and tampering).
//! Known answers come from fixtures generated by tools/crypto_cipher_vectors_gen.go.

mod common;

use common::{fixture, Field};
use rust_stdlib_crypto::cipher::{
    self, Aead, Block, BlockMode, Stream, StreamReader, StreamWriter, GCM_NONCE_SIZES,
};
use rust_stdlib_crypto::{aes, des, rc4};
use std::io::{Read, Write};

fn unhex(text: &str) -> Vec<u8> {
    assert!(text.len().is_multiple_of(2), "odd hex {text}");
    (0..text.len())
        .step_by(2)
        .map(|at| u8::from_str_radix(&text[at..at + 2], 16).expect("hex"))
        .collect()
}

/// A column Go wrote as a hex string literal.
fn hex_column(field: &Field) -> Vec<u8> {
    unhex(&field.hex_text())
}

/// Deterministic test data.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn bytes(&mut self, len: usize) -> Vec<u8> {
        (0..len).map(|_| self.next() as u8).collect()
    }

    fn below(&mut self, bound: usize) -> usize {
        (self.next() % bound as u64) as usize
    }
}

fn aes_cipher(key: &[u8]) -> aes::Cipher {
    aes::Cipher::new(key).expect("valid AES key")
}

fn encrypt_block(block: &dyn Block, src: &[u8]) -> Vec<u8> {
    let mut out = vec![0; block.block_size()];
    block.encrypt(&mut out, src).expect("block");
    out
}

fn decrypt_block(block: &dyn Block, src: &[u8]) -> Vec<u8> {
    let mut out = vec![0; block.block_size()];
    block.decrypt(&mut out, src).expect("block");
    out
}

