// crypto/aes

#[test]
fn aes_fips197_examples() {
    let rows = fixture("aes.tsv");
    assert_eq!(rows.len(), 4);
    for (i, row) in rows.iter().enumerate() {
        let (key, input, want) = (row[0].bytes(), row[1].bytes(), row[2].bytes());
        let block = aes_cipher(&key);
        assert_eq!(block.block_size(), aes::BLOCK_SIZE);
        assert_eq!(encrypt_block(&block, &input), want, "encrypt #{i}");
        assert_eq!(decrypt_block(&block, &want), input, "decrypt #{i}");
    }
}

#[test]
fn aes_key_size_errors_use_go_messages() {
    for length in 0..=70 {
        let result = aes::Cipher::new(&vec![0; length]);
        if matches!(length, 16 | 24 | 32) {
            assert!(result.is_ok(), "key length {length}");
        } else {
            let error = result.unwrap_err();
            assert_eq!(error, aes::KeySizeError(length));
            assert_eq!(
                error.to_string(),
                format!("crypto/aes: invalid key size {length}")
            );
        }
    }
}

#[test]
fn aes_block_short_buffers_are_errors() {
    let block = aes_cipher(&[0; 16]);
    let mut out = [0u8; 16];
    let short = block.encrypt(&mut out, &[0; 15]).unwrap_err();
    assert_eq!(short.to_string(), "crypto/aes: input not full block");
    let short = block.decrypt(&mut out[..15], &[0; 16]).unwrap_err();
    assert_eq!(short.to_string(), "crypto/aes: output not full block");
    // Longer buffers use only their first block, as in Go.
    let mut long = [0xAAu8; 20];
    block.encrypt(&mut long, &[0; 20]).unwrap();
    assert_eq!(long[..16], encrypt_block(&block, &[0; 16])[..]);
    assert_eq!(long[16..], [0xAA; 4]);
}

