#[test]
fn des_error_messages_and_sizes() {
    assert_eq!(
        des::Cipher::new(&[0; 7]).unwrap_err().to_string(),
        "crypto/des: invalid key size 7"
    );
    assert_eq!(
        des::TripleDesCipher::new(&[0; 8]).unwrap_err(),
        des::KeySizeError(8)
    );
    assert_eq!(
        des::TripleDesCipher::new(&[0; 16]).unwrap_err().to_string(),
        "crypto/des: invalid key size 16"
    );
    assert_eq!(des::BLOCK_SIZE, 8);
    assert_eq!(des::Cipher::new(&[0; 8]).unwrap().block_size(), 8);
    let block = des::Cipher::new(&[0; 8]).unwrap();
    let mut out = [0u8; 8];
    assert_eq!(
        block.encrypt(&mut out, &[0; 7]).unwrap_err().to_string(),
        "crypto/des: input not full block"
    );
    assert_eq!(
        block
            .decrypt(&mut out[..7], &[0; 8])
            .unwrap_err()
            .to_string(),
        "crypto/des: output not full block"
    );
}

#[test]
fn des_encrypt_and_decrypt_tables() {
    let rows = fixture("des.tsv");
    assert_eq!(rows.len(), 27);
    for (i, row) in rows.iter().enumerate() {
        let block = des::Cipher::new(&row[0].bytes()).unwrap();
        let (input, out) = (row[1].bytes(), row[2].bytes());
        assert_eq!(encrypt_block(&block, &input), out, "encrypt #{i}");
        assert_eq!(decrypt_block(&block, &out), input, "decrypt #{i}");
    }
}

#[test]
fn des_weak_and_semi_weak_keys() {
    for (i, row) in fixture("des_weak.tsv").iter().enumerate() {
        let block = des::Cipher::new(&row[0].bytes()).unwrap();
        let input = row[1].bytes();
        let twice = encrypt_block(&block, &encrypt_block(&block, &input));
        assert_eq!(twice, input, "weak key #{i}");
    }
    let rows = fixture("des_semiweak.tsv");
    assert_eq!(rows.len(), 6);
    for (i, row) in rows.iter().enumerate() {
        let first = des::Cipher::new(&row[0].bytes()).unwrap();
        let second = des::Cipher::new(&row[2].bytes()).unwrap();
        let input = row[1].bytes();
        let result = encrypt_block(&second, &encrypt_block(&first, &input));
        assert_eq!(result, input, "semi-weak pair #{i}");
    }
}

