#[test]
fn nist_800_20_known_answers() {
    // Table A.1: variable plaintext under the 0x01... key.
    let key = fixture("des_a1_key.tsv")[0][0].bytes();
    let block = des::TripleDesCipher::new(&key).unwrap();
    let rows = fixture("des_a1.tsv");
    assert_eq!(rows.len(), 64);
    for (i, row) in rows.iter().enumerate() {
        let (input, out) = (row[1].bytes(), row[2].bytes());
        assert_eq!(encrypt_block(&block, &input), out, "A.1 encrypt #{i}");
        assert_eq!(decrypt_block(&block, &out), input, "A.1 decrypt #{i}");
        // The inverse and initial permutation tests swap the directions.
        assert_eq!(encrypt_block(&block, &out), input, "A.1 inverse #{i}");
        assert_eq!(decrypt_block(&block, &input), out, "A.1 initial #{i}");
    }
    // Tables A.2 and A.3: variable keys over a fixed plaintext.
    for (table, plaintext_file, count) in [
        ("des_a2.tsv", "des_a2_plaintext.tsv", 56),
        ("des_a3.tsv", "des_a3_plaintext.tsv", 32),
    ] {
        let plaintext = fixture(plaintext_file)[0][0].bytes();
        let rows = fixture(table);
        assert_eq!(rows.len(), count, "{table}");
        for (i, row) in rows.iter().enumerate() {
            let block = des::TripleDesCipher::new(&row[0].bytes()).unwrap();
            let out = row[2].bytes();
            assert_eq!(
                encrypt_block(&block, &plaintext),
                out,
                "{table} encrypt #{i}"
            );
            assert_eq!(
                decrypt_block(&block, &out),
                plaintext,
                "{table} decrypt #{i}"
            );
        }
    }
    // Table A.4: substitution tables.
    let rows = fixture("des_a4.tsv");
    assert_eq!(rows.len(), 19);
    for (i, row) in rows.iter().enumerate() {
        let block = des::TripleDesCipher::new(&row[0].bytes()).unwrap();
        let (input, out) = (row[1].bytes(), row[2].bytes());
        assert_eq!(encrypt_block(&block, &input), out, "A.4 encrypt #{i}");
        assert_eq!(decrypt_block(&block, &out), input, "A.4 decrypt #{i}");
    }
}

