#[test]
fn rc4_golden_keystreams_in_every_chunking() {
    let rows = fixture("rc4.tsv");
    assert_eq!(rows.len(), 6);
    for (index, row) in rows.iter().enumerate() {
        let (key, keystream) = (row[0].bytes(), row[1].bytes());
        let data: Vec<u8> = (0..keystream.len()).map(|i| i as u8).collect();
        let expect: Vec<u8> = data.iter().zip(&keystream).map(|(d, k)| d ^ k).collect();
        for size in 1..=keystream.len() {
            let mut cipher = rc4::Cipher::new(&key).unwrap();
            for (offset, chunk) in data.chunks(size).enumerate() {
                let start = offset * size;
                let mut out = vec![0; chunk.len()];
                cipher.xor_key_stream(&mut out, chunk).unwrap();
                assert_eq!(out, expect[start..start + chunk.len()], "#{index}@{start}");
            }
        }
    }
}

#[test]
fn rc4_whole_block_equals_byte_at_a_time() {
    let rows = fixture("rc4.tsv");
    let (key_a, key_b) = (rows[0][0].bytes(), rows[1][0].bytes());
    let mut one_by_one = vec![0u8; 1 << 16];
    let mut a = rc4::Cipher::new(&key_a).unwrap();
    let mut b = rc4::Cipher::new(&key_b).unwrap();
    for i in 0..one_by_one.len() {
        a.xor_key_stream_in_place(&mut one_by_one[i..i + 1]);
        b.xor_key_stream_in_place(&mut one_by_one[i..i + 1]);
    }
    let mut whole = vec![0u8; 1 << 16];
    let mut a = rc4::Cipher::new(&key_a).unwrap();
    let mut b = rc4::Cipher::new(&key_b).unwrap();
    a.xor_key_stream_in_place(&mut whole);
    b.xor_key_stream_in_place(&mut whole);
    assert_eq!(one_by_one, whole);
}

#[test]
fn rc4_key_sizes_errors_and_reset() {
    for length in [0, 257, 300] {
        let error = rc4::Cipher::new(&vec![1; length]).unwrap_err();
        assert_eq!(error, rc4::KeySizeError(length));
        assert_eq!(
            error.to_string(),
            format!("crypto/rc4: invalid key size {length}")
        );
    }
    for length in [1, 2, 255, 256] {
        assert!(rc4::Cipher::new(&vec![1; length]).is_ok());
    }
    let mut cipher = rc4::Cipher::new(b"key").unwrap();
    let mut out = [0u8; 4];
    let error = cipher.xor_key_stream(&mut out[..2], b"abcd").unwrap_err();
    assert_eq!(error.to_string(), "crypto/rc4: output smaller than input");
    // Empty input is accepted whatever dst is.
    cipher.xor_key_stream(&mut [], &[]).unwrap();
    // After Reset the key stream is all zeros: data passes through.
    cipher.reset();
    cipher.xor_key_stream(&mut out, b"abcd").unwrap();
    assert_eq!(&out, b"abcd");
    // dst may be longer than src.
    let mut fresh = rc4::Cipher::new(b"key").unwrap();
    let mut long = [0xEEu8; 6];
    fresh.xor_key_stream(&mut long, b"abcd").unwrap();
    assert_eq!(long[4..], [0xEE, 0xEE]);
}

