#[test]
fn stream_reader_and_writer_round_trip() {
    let block = aes_cipher(&common_key(256));
    let iv = [3u8; 16];
    let plaintext: Vec<u8> = (0..1000u32).map(|i| (i * 7) as u8).collect();

    let mut writer = StreamWriter::new(cipher::ctr(&block, &iv).unwrap(), Vec::new());
    for chunk in plaintext.chunks(33) {
        assert_eq!(writer.write(chunk).unwrap(), chunk.len());
    }
    writer.flush().unwrap();
    let ciphertext = writer.w.clone();
    writer.close().unwrap();
    let mut whole = vec![0; plaintext.len()];
    cipher::ctr(&block, &iv)
        .unwrap()
        .xor_key_stream(&mut whole, &plaintext)
        .unwrap();
    assert_eq!(ciphertext, whole);

    let mut reader = StreamReader {
        s: cipher::ctr(&block, &iv).unwrap(),
        r: &ciphertext[..],
    };
    let mut recovered: Vec<u8> = Vec::new();
    let mut buf = [0u8; 61];
    loop {
        let n = reader.read(&mut buf).unwrap();
        if n == 0 {
            break;
        }
        recovered.extend(&buf[..n]);
    }
    assert_eq!(recovered, plaintext);
}

/// A writer that accepts at most `limit` bytes per call.
struct Trickle(usize);

impl Write for Trickle {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        Ok(buf.len().min(self.0))
    }

    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

#[test]
fn stream_writer_short_write_is_an_error() {
    let block = aes_cipher(&[0; 16]);
    let mut writer = StreamWriter::new(cipher::ofb(&block, &[0; 16]).unwrap(), Trickle(2));
    let error = writer.write(b"abcdef").unwrap_err();
    assert_eq!(error.kind(), std::io::ErrorKind::WriteZero);
    assert_eq!(error.to_string(), "short write");
    assert_eq!(writer.write(b"ab").unwrap(), 2);
}

