#[test]
fn gcm_nist_vectors_from_go() {
    let rows = fixture("gcm.tsv");
    assert_eq!(rows.len(), 49);
    let mut zero_nonce = 0;
    for (i, row) in rows.iter().enumerate() {
        let key = hex_column(&row[0]);
        let mut nonce = hex_column(&row[1]);
        let plaintext = hex_column(&row[2]);
        let mut ad = hex_column(&row[3]);
        let result = hex_column(&row[4]);
        let block = aes_cipher(&key);
        let tag_size = result.len() - plaintext.len();

        let aead = if tag_size != 16 {
            cipher::gcm_with_tag_size(&block, tag_size).unwrap()
        } else if nonce.is_empty() {
            let error = cipher::gcm_with_nonce_size(&block, 0).err().unwrap();
            assert_eq!(
                error.to_string(),
                "cipher: the nonce can't have zero length"
            );
            zero_nonce += 1;
            continue;
        } else if nonce.len() != 12 {
            cipher::gcm_with_nonce_size(&block, nonce.len()).unwrap()
        } else {
            cipher::gcm(&block).unwrap()
        };
        assert_eq!(aead.nonce_size(), nonce.len());
        assert_eq!(aead.overhead(), tag_size);

        let mut sealed = Vec::new();
        aead.seal(&mut sealed, &nonce, &plaintext, &ad).unwrap();
        assert_eq!(sealed, result, "#{i} seal");

        let mut opened = Vec::new();
        aead.open(&mut opened, &nonce, &sealed, &ad).unwrap();
        assert_eq!(opened, plaintext, "#{i} open");

        let fails = |nonce: &[u8], ciphertext: &[u8], ad: &[u8]| {
            let mut out = b"keep".to_vec();
            let error = aead.open(&mut out, nonce, ciphertext, ad).unwrap_err();
            assert!(error.is_authentication_failure(), "#{i}: {error}");
            assert_eq!(out, b"keep", "#{i}: dst changed by a failed open");
        };
        if !ad.is_empty() {
            ad[0] ^= 0x80;
            fails(&nonce, &sealed, &ad);
            ad[0] ^= 0x80;
        }
        nonce[0] ^= 0x80;
        fails(&nonce, &sealed, &ad);
        nonce[0] ^= 0x80;
        let mut tampered = sealed.clone();
        tampered[0] ^= 0x80;
        fails(&nonce, &tampered, &ad);
        let last = tampered.len() - 1;
        tampered[0] ^= 0x80;
        tampered[last] ^= 1;
        fails(&nonce, &tampered, &ad);
    }
    assert_eq!(zero_nonce, 1);
}

#[test]
fn gcm_invalid_tag_sizes() {
    let block = aes_cipher(&unhex("ab72c77b97cb5fe9a382d9fe81ffdbed"));
    for tag_size in [0, 1, 11, 17, 100] {
        let error = cipher::gcm_with_tag_size(&block, tag_size)
            .err()
            .expect("invalid tag size");
        assert_eq!(error.to_string(), "cipher: incorrect tag size given to GCM");
    }
    for tag_size in 12..=16 {
        assert_eq!(
            cipher::gcm_with_tag_size(&block, tag_size)
                .unwrap()
                .overhead(),
            tag_size
        );
    }
}

#[test]
fn gcm_failed_open_releases_nothing() {
    let block = aes_cipher(&unhex("ab72c77b97cb5fe9a382d9fe81ffdbed"));
    let nonce = unhex("54cc7dc2c37ec006bcc6d1db");
    let ciphertext = unhex("0e1bde206a07a9c2c1b65300f8c649972b4401346697138c7a4891ee59867d0c");
    let aead = cipher::gcm(&block).unwrap();
    let mut dst = vec![42u8; 3];
    let error = aead.open(&mut dst, &nonce, &ciphertext, &[]).unwrap_err();
    assert_eq!(error.to_string(), "cipher: message authentication failed");
    assert_eq!(dst, [42, 42, 42]);
    // Too short for a tag.
    assert!(aead
        .open(&mut dst, &nonce, &ciphertext[..15], &[])
        .unwrap_err()
        .is_authentication_failure());
}

#[test]
fn gcm_counter_wrap() {
    // The last 32 bits of the counter wrap (Go's TestGCMCounterWrap).
    let tests = [
        ("0fa72e25", "37e1948cdfff09fbde0c40ad99fee4a7"),
        ("afe05cc1", "438f3aa9fee5e54903b1927bca26bbdf"),
        ("9ffecbef", "7b88ca424df9703e9e8611071ec7e16e"),
        ("ffc3e5b3", "38d49c86e0abe853ac250e66da54c01a"),
        ("cfdd729d", "e08402eaac36a1a402e09b1bd56500e8"),
        ("010ae3d486", "5405bb490b1f95d01e2ba735687154bc"),
        ("01b1107a9d", "939a585f342e01e17844627492d44dbf"),
    ];
    let key = aes_cipher(&[0; 16]);
    let plaintext = vec![0u8; 16 * 17 + 1];
    for (i, (nonce, tag)) in tests.iter().enumerate() {
        let nonce = unhex(nonce);
        let aead = cipher::gcm_with_nonce_size(&key, nonce.len()).unwrap();
        let mut sealed = Vec::new();
        aead.seal(&mut sealed, &nonce, &plaintext, &[]).unwrap();
        assert_eq!(sealed[plaintext.len()..], unhex(tag)[..], "test[{i}]");
        let mut opened = Vec::new();
        aead.open(&mut opened, &nonce, &sealed, &[]).unwrap();
        assert_eq!(opened, plaintext, "test[{i}]");
    }
}

#[test]
fn gcm_length_rules_use_go_messages() {
    let block = aes_cipher(&[9; 32]);
    let aead = cipher::gcm(&block).unwrap();
    let mut dst = vec![1u8];
    for nonce_len in [0, 11, 13] {
        let nonce = vec![0; nonce_len];
        assert_eq!(
            aead.seal(&mut dst, &nonce, b"x", &[])
                .unwrap_err()
                .to_string(),
            "crypto/cipher: incorrect nonce length given to GCM"
        );
        assert_eq!(
            aead.open(&mut dst, &nonce, &[0; 32], &[])
                .unwrap_err()
                .to_string(),
            "crypto/cipher: incorrect nonce length given to GCM"
        );
    }
    assert_eq!(dst, [1], "failed calls append nothing");

    // Appends after existing contents, like Go's dst argument.
    aead.seal(&mut dst, &[0; 12], b"abc", b"ad").unwrap();
    assert_eq!(dst.len(), 1 + 3 + 16);
    assert_eq!(dst[0], 1);
    let mut plain = b"> ".to_vec();
    aead.open(&mut plain, &[0; 12], &dst[1..], b"ad").unwrap();
    assert_eq!(plain, b"> abc");

    // seal_in_place and open_in_place are Go's plaintext[:0] idiom.
    let mut buf = b"in place".to_vec();
    aead.seal_in_place(&mut buf, &[5; 12], &[]).unwrap();
    assert_eq!(buf.len(), 8 + 16);
    let before = buf.clone();
    let mut bad = buf.clone();
    bad[2] ^= 1;
    assert!(aead.open_in_place(&mut bad, &[5; 12], &[]).is_err());
    assert_eq!(bad.len(), before.len(), "buf unchanged by a failed open");
    aead.open_in_place(&mut buf, &[5; 12], &[]).unwrap();
    assert_eq!(buf, b"in place");
}

#[test]
fn gcm_requires_a_128_bit_block() {
    let des = des::Cipher::new(&[1; 8]).unwrap();
    let message = |result: Result<Box<dyn Aead + '_>, cipher::Error>| match result {
        Err(error) => error.to_string(),
        Ok(_) => panic!("expected an error"),
    };
    assert_eq!(
        message(cipher::gcm(&des)),
        "cipher: NewGCM requires 128-bit block cipher"
    );
    // Go checks the tag and nonce sizes first.
    assert_eq!(
        message(cipher::gcm_with_tag_size(&des, 11)),
        "cipher: incorrect tag size given to GCM"
    );
    assert_eq!(
        message(cipher::gcm_with_nonce_size(&des, 0)),
        "cipher: the nonce can't have zero length"
    );
    assert_eq!(
        message(cipher::gcm_with_random_nonce(&des)),
        "cipher: NewGCMWithRandomNonce requires aes.Block"
    );
    // A 128-bit block that is not AES works in GCM but not with random nonces.
    let custom = CustomBlock { key: vec![5; 16] };
    let aead = cipher::gcm(&custom).unwrap();
    let mut sealed = Vec::new();
    aead.seal(&mut sealed, &[0; 12], b"custom", &[]).unwrap();
    let mut opened = Vec::new();
    aead.open(&mut opened, &[0; 12], &sealed, &[]).unwrap();
    assert_eq!(opened, b"custom");
    assert_eq!(
        message(cipher::gcm_with_random_nonce(&custom)),
        "cipher: NewGCMWithRandomNonce requires aes.Block"
    );
}

#[test]
fn gcm_nonce_and_tag_size_matrix() {
    let mut rng = Rng(0x1234_5678_9ABC_DEF0);
    for key_len in [16, 24, 32] {
        let block = aes_cipher(&rng.bytes(key_len));
        for &nonce_size in &GCM_NONCE_SIZES {
            let aead = cipher::gcm_with_nonce_size(&block, nonce_size).unwrap();
            check_aead(&aead, &mut rng);
        }
        for tag_size in 12..=16 {
            check_aead(
                &cipher::gcm_with_tag_size(&block, tag_size).unwrap(),
                &mut rng,
            );
        }
    }
    let block = aes_cipher(&[0; 16]);
    for size in [33, 37, 129, 1000] {
        let error = cipher::gcm_with_nonce_size(&block, size).err().unwrap();
        assert!(error.to_string().contains("is not supported"), "{size}");
    }
}

/// Go's cryptotest.TestAEAD properties: round trips over many sizes, tampering
/// anywhere is detected, and `overhead` and `nonce_size` are honest.
fn check_aead(aead: &dyn Aead, rng: &mut Rng) {
    for len in [0, 1, 15, 16, 17, 31, 32, 33, 100, 257] {
        for ad_len in [0, 1, 16, 33] {
            let nonce = rng.bytes(aead.nonce_size());
            let plaintext = rng.bytes(len);
            let ad = rng.bytes(ad_len);
            let mut sealed = Vec::new();
            aead.seal(&mut sealed, &nonce, &plaintext, &ad).unwrap();
            assert_eq!(sealed.len(), len + aead.overhead());
            let mut opened = Vec::new();
            aead.open(&mut opened, &nonce, &sealed, &ad).unwrap();
            assert_eq!(opened, plaintext);
            for position in [0, sealed.len() / 2, sealed.len() - 1] {
                let mut tampered = sealed.clone();
                tampered[position] ^= 0x40;
                let mut out = Vec::new();
                assert!(aead.open(&mut out, &nonce, &tampered, &ad).is_err());
                assert!(out.is_empty());
            }
            if ad_len > 0 {
                let mut bad_ad = ad.clone();
                bad_ad[0] ^= 1;
                assert!(aead
                    .open(&mut Vec::new(), &nonce, &sealed, &bad_ad)
                    .is_err());
            }
        }
    }
}

#[test]
fn gcm_with_random_nonce() {
    let block = aes_cipher(&unhex("2b7e151628aed2a6abf7158809cf4f3c"));
    let aead = cipher::gcm_with_random_nonce(&block).unwrap();
    assert_eq!(aead.nonce_size(), 0);
    assert_eq!(aead.overhead(), 28);

    let mut first = Vec::new();
    let mut second = Vec::new();
    aead.seal(&mut first, &[], b"message", b"ad").unwrap();
    aead.seal(&mut second, &[], b"message", b"ad").unwrap();
    assert_eq!(first.len(), 7 + 28);
    assert_ne!(first, second, "each call draws a fresh nonce");

    let mut opened = Vec::new();
    aead.open(&mut opened, &[], &first, b"ad").unwrap();
    assert_eq!(opened, b"message");
    // The nonce is the first 12 bytes of the output, as a plain GCM can check.
    let plain = cipher::gcm(&block).unwrap();
    let mut via_plain = Vec::new();
    plain
        .open(&mut via_plain, &first[..12], &first[12..], b"ad")
        .unwrap();
    assert_eq!(via_plain, b"message");

    for (nonce, name) in [(&[0u8][..], "seal"), (&[0u8; 12][..], "open")] {
        let error = if name == "seal" {
            aead.seal(&mut Vec::new(), nonce, b"x", &[]).unwrap_err()
        } else {
            aead.open(&mut Vec::new(), nonce, &first, &[]).unwrap_err()
        };
        assert_eq!(
            error.to_string(),
            "crypto/cipher: non-empty nonce passed to GCMWithRandomNonce"
        );
    }
    for short in [0, 1, 27] {
        let error = aead
            .open(&mut Vec::new(), &[], &first[..short], &[])
            .unwrap_err();
        assert!(error.is_authentication_failure());
    }
    let mut tampered = first.clone();
    tampered[3] ^= 1;
    assert!(aead.open(&mut Vec::new(), &[], &tampered, b"ad").is_err());
    check_aead(&aead, &mut Rng(77));
    let mut buf = b"random in place".to_vec();
    aead.seal_in_place(&mut buf, &[], &[]).unwrap();
    aead.open_in_place(&mut buf, &[], &[]).unwrap();
    assert_eq!(buf, b"random in place");
}

#[test]
fn boxed_trait_objects_delegate() {
    let block = aes_cipher(&[2; 16]);
    let mut mode: Box<dyn BlockMode> = Box::new(cipher::cbc_encrypter(&block, &[0; 16]).unwrap());
    assert_eq!(mode.block_size(), 16);
    let mut data = [0u8; 16];
    mode.crypt_blocks_in_place(&mut data).unwrap();
    let mut stream: Box<dyn Stream> = Box::new(cipher::ctr(&block, &[0; 16]).unwrap());
    stream.xor_key_stream_in_place(&mut data);
    let aead: Box<dyn Aead> = Box::new(cipher::gcm(&block).unwrap());
    assert_eq!(aead.overhead(), 16);
}
